// Jonker-Volgenant LAPJV, dense square, minimization
#include <vector>
#include <cmath>
#include <limits>
#include <cstring>
#include <algorithm>
#include <cstdint>

extern "C" {

// rowsol[i] = assigned column for row i
// cost is row-major n*n
int lapjv(int n, const double* cost, int* rowsol, int* colsol) {
    const double INF = 1e18;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<double> d(n);
    std::vector<int> pred(n), colsol_local(n, -1), rowsol_local(n, -1);
    std::vector<int> free_rows;
    free_rows.reserve(n);

    // column reduction
    std::vector<int> matches(n, 0);
    for (int i = n - 1; i >= 0; --i) {
        double minv = INF;
        int minj = 0;
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            double r = row[j] - v[j];
            if (r < minv) { minv = r; minj = j; }
        }
        u[i] = minv;
        if (matches[minj] == 0) {
            matches[minj] = 1;
            rowsol_local[i] = minj;
            colsol_local[minj] = i;
        } else {
            // second min?
            free_rows.push_back(i);
        }
    }

    // augment free rows (simple successive shortest path with potentials)
    // Use Dijkstra-like with potentials (reduced costs nonnegative)
    std::vector<char> seen(n);
    std::vector<int> todo;
    todo.reserve(n);

    // process free rows in reverse order of insertion (like JV often does from low index)
    // We'll just process as is
    for (int fr : free_rows) {
        // Dijkstra
        std::fill(d.begin(), d.end(), INF);
        std::fill(pred.begin(), pred.end(), -1);
        std::fill(seen.begin(), seen.end(), 0);
        int sink = -1;
        int i0 = fr;
        // init from free row
        const double* row = cost + (size_t)i0 * n;
        double ui = u[i0];
        for (int j = 0; j < n; ++j) {
            d[j] = row[j] - v[j] - ui;
            pred[j] = i0;
        }
        while (true) {
            // find unscanned min
            double mind = INF;
            int jmin = -1;
            for (int j = 0; j < n; ++j) if (!seen[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            if (jmin < 0) break;
            seen[jmin] = 1;
            int i = colsol_local[jmin];
            if (i < 0) { sink = jmin; break; }
            // update potentials scan
            const double* rowi = cost + (size_t)i * n;
            double ui2 = u[i];
            double vj = v[jmin];
            for (int j = 0; j < n; ++j) if (!seen[j]) {
                double nd = mind + rowi[j] - v[j] - ui2 - (/*reduced of matched edge*/ 0);
                // reduced cost of (i,j) relative to matched (i,jmin):
                // d[j] candidate = d[jmin] + c[i,j]-u[i]-v[j] - (c[i,jmin]-u[i]-v[jmin])
                // = mind + c[i,j] - v[j] - (c[i,jmin] - v[jmin])
                double alt = mind + (rowi[j] - v[j]) - (rowi[jmin] - vj);
                if (alt < d[j]) { d[j] = alt; pred[j] = i; }
            }
        }
        if (sink < 0) return 1;
        // update duals
        double delta = d[sink];
        for (int j = 0; j < n; ++j) if (seen[j]) v[j] += d[j] - delta;
        u[i0] += delta;
        // augment
        int j = sink;
        while (true) {
            int i = pred[j];
            int jnext = rowsol_local[i];
            rowsol_local[i] = j;
            colsol_local[j] = i;
            if (i == i0) break;
            j = jnext;
        }
    }
    std::memcpy(rowsol, rowsol_local.data(), n * sizeof(int));
    std::memcpy(colsol, colsol_local.data(), n * sizeof(int));
    return 0;
}

}
