import ctypes, numpy as np, time
from reference import Task
import ot
lib = ctypes.CDLL("/tmp/libjv.dylib")
lib.lapjv.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]
lib.lapjv.restype = ctypes.c_int

def solve(M):
    n = M.shape[0]
    rowsol = np.empty(n, np.int32)
    colsol = np.empty(n, np.int32)
    rc = lib.lapjv(n, M.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
                   rowsol.ctypes.data_as(ctypes.POINTER(ctypes.c_int)),
                   colsol.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    return rc, rowsol, colsol

t = Task()
ok=True
times=[]
for s in range(3):
    p = t.generate_problem(200, s+10)
    a = np.asarray(p["source_weights"], np.float64)
    b = np.asarray(p["target_weights"], np.float64)
    M = np.ascontiguousarray(p["cost_matrix"], np.float64)
    t0=time.perf_counter()
    rc, rowsol, colsol = solve(M)
    times.append(time.perf_counter()-t0)
    G = np.zeros_like(M)
    G[np.arange(200), rowsol] = a
    Gref = ot.lp.emd(a,b,M, check_marginals=False)
    match = np.allclose(G, Gref)
    print(s, "rc", rc, "time", times[-1], "match", match, "unique", len(set(rowsol.tolist()))==200)
    if not match: ok=False
print("mean", np.mean(times), "ok", ok)
