{"command":"cat > "$HOME/lapbuild/lapjv.h" << 'ENDH'
#pragma once
#include <vector>
#include <limits>
#include <algorithm>
#include <cstring>

// Jonker-Volgenant algorithm for dense square assignment (minimization).
// Returns 0 on success. rowsol[i] = assigned column.
inline int lapjv_solve(int n, const double* cost, int* rowsol) {
    const double INF = std::numeric_limits<double>::infinity();
    std::vector<int> colsol(n, -1);
    std::vector<double> u(n), v(n, 0.0);
    std::vector<double> d(n);
    std::vector<int> pred(n), collist(n), matches(n, 0);
    std::vector<int> free_rows;
    free_rows.reserve(n);

    // Column reduction: scan rows from last to first.
    // For each row, find the two smallest reduced costs.
    for (int i = n - 1; i >= 0; --i) {
        const double* row = cost + (size_t)i * n;
        double min1 = INF, min2 = INF;
        int j1 = -1;
        for (int j = 0; j < n; ++j) {
            double h = row[j] - v[j];
            if (h < min2) {
                if (h >= min1) {
                    min2 = h;
                } else {
                    min2 = min1;
                    min1 = h;
                    j1 = j;
                }
            }
        }
        u[i] = min1;
        if (min2 < INF) v[j1] -= (min2 - min1);  // reduction: make min unique-ish
        if (matches[j1] == 0) {
            matches[j1] = 1;
            rowsol[i] = j1;
            colsol[j1] = i;
        } else {
            rowsol[i] = -1;
            free_rows.push_back(i);
        }
    }

    // Reduction transfer: for assigned rows, transfer dual so v is consistent
    // (the subtraction above already updates v; unassigned columns keep v=0)

    std::vector<char> todo(n);
    int nfree = (int)free_rows.size();
    if (nfree == 0) return 0;

    // Augmenting row reduction (ARR) — a few passes to assign more rows cheaply
    for (int pass = 0; pass < 2 && nfree; ++pass) {
        int k = 0;
        int new_nfree = 0;
        std::vector<int> still;
        still.reserve(nfree);
        // process low index first: free_rows was pushed high-to-low, so reverse
        for (int t = nfree - 1; t >= 0; --t) {
            int i = free_rows[t];
            const double* row = cost + (size_t)i * n;
            double umin = INF, usub = INF;
            int j1 = -1, j2 = -1;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) {
                        usub = h; j2 = j;
                    } else {
                        usub = umin; j2 = j1;
                        umin = h; j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) {
                v[j1] -= (usub - umin);
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            u[i] = umin;
            if (i0 >= 0) {
                if (umin < usub) {
                    still.push_back(i0); // free the previous
                    rowsol[i] = j1;
                    colsol[j1] = i;
                    rowsol[i0] = -1;
                } else {
                    still.push_back(i);
                }
            } else {
                rowsol[i] = j1;
                colsol[j1] = i;
            }
        }
        free_rows.swap(still);
        nfree = (int)free_rows.size();
    }

    if (nfree == 0) return 0;

    // Augmentation via Dijkstra on reduced costs
    std::vector<char> seen(n);
    for (int fi = 0; fi < nfree; ++fi) {
        int freerow = free_rows[fi];
        if (rowsol[freerow] >= 0) continue; // assigned during? shouldn't

        std::fill(d.begin(), d.end(), INF);
        std::fill(pred.begin(), pred.end(), freerow);
        std::fill(seen.begin(), seen.end(), 0);

        const double* frow = cost + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            collist[j] = j;
        }
        int low = 0, up = 0; // scanned prefix end, end of ready
        // We maintain collist[0:low) scanned, collist[low:up) ready? simpler linear scan of unscanned
        int endofpath = -1;
        double min_d = 0;
        int last_low = 0;

        // Use a threshold scan (JV style) but with simple O(n) find-min which is fine if constant is low;
        // optimize with a moving partition.
        int unscanned = n;
        while (true) {
            if (low == up) {
                // find minimum among unscanned collist[up:n)
                double h = INF;
                int jmin_pos = up;
                for (int p = up; p < n; ++p) {
                    int j = collist[p];
                    if (d[j] <= h) { h = d[j]; jmin_pos = p; }
                }
                // swap to position up
                int tmp = collist[up]; collist[up] = collist[jmin_pos]; collist[jmin_pos] = tmp;
                min_d = h;
                if (h >= INF/2) return 1;
                low = up;
                // gather all equal to h? not necessary
                up = low + 1;
            }
            int j = collist[low];
            ++low; --unscanned;
            if (colsol[j] < 0) { endofpath = j; break; }
            int i = colsol[j];
            const double* row = cost + (size_t)i * n;
            double cred_base = row[j] - v[j] - min_d; // = reduced of matched edge relative
            // actually matched reduced cost should be 0 if duals feasible. Use difference form:
            double base = row[j] - v[j];
            for (int p = low; p < n; ++p) {
                int j2 = collist[p];
                double h = row[j2] - v[j2] - base + min_d;
                if (h < d[j2]) {
                    d[j2] = h;
                    pred[j2] = i;
                }
            }
        }
        // update dual variables
        for (int p = 0; p < low; ++p) {
            int j = collist[p];
            v[j] += d[j] - min_d;
        }
        // augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
    }
    return 0;
}
ENDH
