{"command":"cat > "$HOME/lapbuild/ssp.cpp" << 'EOF'
// Successive shortest paths for the dense assignment problem (minimization).
// Maintains feasible duals (u, v) with reduced costs c_ij - u_i - v_j >= 0.
// Initial: v=0, u_i = min_j c_ij, no assignments. Then augment n times.
#include <vector>
#include <cstring>
#include <cstdint>
#include <algorithm>

extern "C" int lapjv(int n, const double* cost, int* rowsol) {
    const double INF = 1e100;
    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> colsol(n, -1);
    std::vector<int> pred(n);
    std::vector<double> dist(n);
    std::vector<char> seen(n);
    std::vector<int> cols(n);

    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        double m = row[0];
        for (int j = 1; j < n; ++j) if (row[j] < m) m = row[j];
        u[i] = m;
        rowsol[i] = -1;
    }

    for (int iter = 0; iter < n; ++iter) {
        // pick a free row: row `iter` is still free if we always augment a new one,
        // but after path updates only the starting free row gets assigned and one stays free.
        // We start from a specific free row each time. Find one.
        int freerow = -1;
        for (int i = 0; i < n; ++i) if (rowsol[i] < 0) { freerow = i; break; }

        for (int j = 0; j < n; ++j) {
            cols[j] = j;
            dist[j] = cost[(size_t)freerow * n + j] - u[freerow] - v[j];
            pred[j] = freerow;
            seen[j] = 0;
        }
        int low = 0;          // number of scanned columns (front of cols)
        int endofpath = -1;
        double mind = 0;

        while (true) {
            // min among cols[low:n)
            double h = INF;
            int pmin = low;
            for (int p = low; p < n; ++p) {
                int j = cols[p];
                if (dist[j] < h) { h = dist[j]; pmin = p; }
            }
            // move to front
            int tmp = cols[low]; cols[low] = cols[pmin]; cols[pmin] = tmp;
            mind = h;
            int j = cols[low];
            ++low;
            seen[j] = 1;
            if (colsol[j] < 0) { endofpath = j; break; }
            int i = colsol[j];
            const double* row = cost + (size_t)i * n;
            double base = row[j] - u[i] - v[j]; // should be ~0
            for (int p = low; p < n; ++p) {
                int j2 = cols[p];
                double alt = mind + (row[j2] - u[i] - v[j2]) - base;
                if (alt < dist[j2]) {
                    dist[j2] = alt;
                    pred[j2] = i;
                }
            }
        }

        // dual update
        u[freerow] += mind;
        for (int p = 0; p < low - 1; ++p) {
            int j = cols[p];
            v[j] += dist[j] - mind;
            int i = colsol[j];
            if (i >= 0) u[i] -= dist[j] - mind;
        }
        // also the sink column's v? sink is unassigned; its reduced cost becomes 0 by raising? 
        // Standard: for scanned columns including sink:
        // v[j] += dist[j] - mind for all scanned j (incl sink where dist=mind so +0)
        // u[i] -= dist[matched] - mind for matched rows of scanned columns except we already
        // handled freerow separately (u[freerow] += mind) which equals u[freerow] -= (0 - mind)
        // if we think of freerow's "dist label" as 0.
        // The loop above excluded sink (low-1 is last scanned which is sink). Good, sink v unchanged
        // because dist[sink]-mind = 0.

        // augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
    }
    return 0;
}
