// Fast successive shortest paths assignment, dense square, minimization.
// Column-reduction initialization + Dijkstra augmentation with duals.
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <vector>

extern "C" int lapjv(int n, const double* __restrict cost, int* __restrict rowsol) {
    const double INF = 1e100;
    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> colsol(n, -1);
    std::vector<int> pred(n);
    std::vector<double> dist(n);
    std::vector<int> cols(n);
    std::vector<int> free_rows;
    free_rows.reserve(n);

    // Initialize duals and a partial matching by column reduction (JV-style),
    // scanning rows from the bottom so the first claimant of a column keeps it
    // only if unique minimum; otherwise column dual is reduced.
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    for (int i = n - 1; i >= 0; --i) {
        const double* row = cost + (size_t)i * n;
        double min1 = INF, min2 = INF;
        int j1 = 0;
        for (int j = 0; j < n; ++j) {
            double h = row[j] - v[j];
            if (h < min1) { min2 = min1; min1 = h; j1 = j; }
            else if (h < min2) min2 = h;
        }
        u[i] = min1;
        double slack = (min2 < INF/2) ? (min2 - min1) : 0.0;
        v[j1] -= slack;  // may break previous reduced-cost feasibility; repaired below
        if (colsol[j1] < 0) {
            colsol[j1] = i;
            rowsol[i] = j1;
        } else {
            free_rows.push_back(i);
        }
    }

    // Recompute u to restore feasibility: u_i = min_j (c_ij - v_j), keep matching if still tight.
    // After v updates, matched edges may no longer be tight and reduced costs may be negative.
    // Reset matching and set u,v feasible, then re-match tight edges greedily.
    // (column reduction above can make reduced costs negative). Do a clean init instead:
    std::fill(v.begin(), v.end(), 0.0);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        double m = row[0];
        int jmin = 0;
        for (int j = 1; j < n; ++j) if (row[j] < m) { m = row[j]; jmin = j; }
        u[i] = m;
        rowsol[i] = -1;
    }
    std::fill(colsol.begin(), colsol.end(), -1);
    free_rows.clear();
    // greedy matching on zero reduced-cost edges, rows high to low (closer to network simplex pivot order?)
    for (int i = n - 1; i >= 0; --i) {
        const double* row = cost + (size_t)i * n;
        int jmin = -1;
        double best = 1e-12; // tolerance for "zero"
        // find a zero-reduced unmatched column; if several, pick smallest index (stable)
        for (int j = 0; j < n; ++j) {
            if (colsol[j] >= 0) continue;
            double r = row[j] - u[i]; // v=0
            if (r <= best) { best = r; jmin = j; break; } // first zero
        }
        if (jmin >= 0 && best <= 1e-9) {
            colsol[jmin] = i;
            rowsol[i] = jmin;
        } else {
            free_rows.push_back(i);
        }
    }

    const int nfree0 = (int)free_rows.size();
    for (int fi = 0; fi < nfree0; ++fi) {
        int freerow = free_rows[fi];
        if (rowsol[freerow] >= 0) continue;

        const double* frow = cost + (size_t)freerow * n;
        double uf = u[freerow];
        for (int j = 0; j < n; ++j) {
            cols[j] = j;
            dist[j] = frow[j] - uf - v[j];
            pred[j] = freerow;
        }
        int low = 0;
        int endofpath = -1;
        double mind = 0;

        while (true) {
            double h = INF;
            int pmin = low;
            int jbest = cols[low];
            for (int p = low; p < n; ++p) {
                int j = cols[p];
                double dj = dist[j];
                if (dj < h) { h = dj; pmin = p; jbest = j; }
            }
            cols[pmin] = cols[low];
            cols[low] = jbest;
            mind = h;
            ++low;
            if (colsol[jbest] < 0) { endofpath = jbest; break; }
            int i = colsol[jbest];
            const double* row = cost + (size_t)i * n;
            double ui = u[i];
            double base = row[jbest] - ui - v[jbest];
            for (int p = low; p < n; ++p) {
                int j2 = cols[p];
                double alt = h + (row[j2] - ui - v[j2]) - base;
                if (alt < dist[j2]) {
                    dist[j2] = alt;
                    pred[j2] = i;
                }
            }
        }

        // dual update
        double diff0 = mind; // freerow label 0 -> mind
        u[freerow] += diff0;
        for (int p = 0; p < low - 1; ++p) {
            int j = cols[p];
            double delta = dist[j] - mind;
            v[j] += delta;
            int i = colsol[j];
            u[i] -= delta;
        }

        // augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
    }
    return 0;
}
