#include <cstring>
#include <algorithm>
#include <vector>
#include <cmath>
#include <omp.h>

// Returns rowsol. Uses OpenMP over the find-min / edge-relax scans.
extern "C" int lapjv(int n, const double* __restrict cost, int* __restrict rowsol) {
    const double INF = 1e100;
    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> colsol(n, -1);
    std::vector<int> pred(n);
    std::vector<double> dist(n);
    std::vector<int> cols(n);

    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        double m = row[0];
        for (int j = 1; j < n; ++j) if (row[j] < m) m = row[j];
        u[i] = m;
        rowsol[i] = -1;
    }

    // greedy zero-reduced matching, low index first (deterministic)
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        double ui = u[i];
        for (int j = 0; j < n; ++j) {
            if (colsol[j] < 0 && row[j] - ui <= 1e-12) {
                colsol[j] = i;
                rowsol[i] = j;
                break;
            }
        }
    }

    // thread-local scratch for parallel min
    const int nthreads = omp_get_max_threads();

    for (int freerow = 0; freerow < n; ++freerow) {
        if (rowsol[freerow] >= 0) continue;
        const double* frow = cost + (size_t)freerow * n;
        double uf = u[freerow];
        for (int j = 0; j < n; ++j) {
            cols[j] = j;
            dist[j] = frow[j] - uf - v[j];
            pred[j] = freerow;
        }
        int remaining = n; // cols[0:remaining) unscanned; we swap mins to the end
        int endofpath = -1;
        double mind = 0;

        while (true) {
            // parallel min over cols[0:remaining)
            double h = INF;
            int pmin = 0;
            #pragma omp parallel
            {
                double lh = INF;
                int lp = 0;
                #pragma omp for nowait
                for (int p = 0; p < remaining; ++p) {
                    double dj = dist[cols[p]];
                    if (dj < lh) { lh = dj; lp = p; }
                }
                #pragma omp critical
                {
                    if (lh < h) { h = lh; pmin = lp; }
                }
            }
            // swap min to end (scanned region grows from the end)
            --remaining;
            int jbest = cols[pmin];
            cols[pmin] = cols[remaining];
            cols[remaining] = jbest;
            mind = h;
            if (colsol[jbest] < 0) { endofpath = jbest; break; }
            int i = colsol[jbest];
            const double* row = cost + (size_t)i * n;
            double ui = u[i];
            double base = row[jbest] - ui - v[jbest];
            double hbase = h - base;
            #pragma omp parallel for
            for (int p = 0; p < remaining; ++p) {
                int j2 = cols[p];
                double alt = hbase + (row[j2] - v[j2]) - ui;
                if (alt < dist[j2]) {
                    dist[j2] = alt;
                    pred[j2] = i;
                }
            }
        }

        u[freerow] += mind;
        // scanned columns are cols[remaining:n) excluding sink at cols[remaining] which is endofpath
        for (int p = remaining + 1; p < n; ++p) {
            int j = cols[p];
            double delta = dist[j] - mind;
            v[j] += delta;
            u[colsol[j]] -= delta;
        }
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jnext;
        }
    }
    return 0;
}
