// Optimization: keep unscanned columns in a dense index array and use a 
// threshold (multiple pivots per scan) like Jonker-Volgenant to cut scan count.
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <vector>

extern "C" int lapjv(int n, const double* __restrict cost, int* __restrict rowsol) {
    const double INF = 1e100;
    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> colsol(n, -1), pred(n), cols(n);
    std::vector<double> dist(n);

    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        double m = row[0];
        for (int j = 1; j < n; ++j) {
            double c = row[j];
            if (c < m) m = c;
        }
        u[i] = m;
        rowsol[i] = -1;
    }
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        double ui = u[i];
        for (int j = 0; j < n; ++j) {
            if (colsol[j] < 0 && row[j] <= ui + 1e-12) {
                colsol[j] = i;
                rowsol[i] = j;
                break;
            }
        }
    }

    for (int freerow = 0; freerow < n; ++freerow) {
        if (rowsol[freerow] >= 0) continue;
        const double* frow = cost + (size_t)freerow * n;
        double uf = u[freerow];
        int remaining = n;
        for (int j = 0; j < n; ++j) {
            cols[j] = j;
            dist[j] = frow[j] - uf - v[j];
            pred[j] = freerow;
        }

        int endofpath = -1;
        double mind_final = 0;
        // scanned stored from the end: cols[remaining:n)
        while (endofpath < 0) {
            // find min dist among remaining
            double hmin = INF;
            int pmin = 0;
            for (int p = 0; p < remaining; ++p) {
                double dj = dist[cols[p]];
                if (dj < hmin) { hmin = dj; pmin = p; }
            }
            // threshold: also take columns within a small band to reduce passes? 
            // Classic JV uses a dynamic threshold. Here take all columns with dist <= hmin
            // (only the min) — but scan the matched row once. Keep simple min.
            --remaining;
            int jbest = cols[pmin];
            cols[pmin] = cols[remaining];
            cols[remaining] = jbest;
            if (colsol[jbest] < 0) { endofpath = jbest; mind_final = hmin; break; }

            int i = colsol[jbest];
            const double* row = cost + (size_t)i * n;
            double ui = u[i];
            double base = row[jbest] - ui - v[jbest];
            double hbase = hmin - base;
            // relax
            int rr = remaining;
            for (int p = 0; p < rr; ++p) {
                int j2 = cols[p];
                double alt = hbase + row[j2] - v[j2] - ui;
                if (alt < dist[j2]) {
                    dist[j2] = alt;
                    pred[j2] = i;
                }
            }
            mind_final = hmin;
        }

        u[freerow] += mind_final;
        for (int p = remaining + 1; p < n; ++p) {
            int j = cols[p];
            double delta = dist[j] - mind_final;
            v[j] += delta;
            u[colsol[j]] -= delta;
        }
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nj = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = nj;
        }
    }
    return 0;
