// Jonker-Volgenant dense LAP, minimization.
// Faithful structure: column reduction, reduction transfer, augmenting row reduction,
// then shortest-path augmentation with a dynamic threshold (multiple columns per scan).
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <vector>
#include <cmath>

static constexpr double BIG = 1e18;

extern "C" int lapjv(int n, const double* __restrict assigncost, int* __restrict rowsol) {
    std::vector<int> colsol(n, -1);
    std::vector<int> freeunassigned;
    freeunassigned.reserve(n);
    std::vector<double> u(n), v(n, 0.0);
    std::vector<double> d(n);
    std::vector<int> pred(n);
    std::vector<int> collist(n);
    std::vector<int> matches(n, 0);

    // ---------- COLUMN REDUCTION ----------
    // From last row to first: find min and second min reduced cost.
    for (int i = n - 1; i >= 0; --i) {
        const double* row = assigncost + (size_t)i * n;
        double min = BIG, second = BIG;
        int jmin = 0;
        for (int j = 0; j < n; ++j) {
            double red = row[j] - v[j];
            if (red < second) {
                if (red >= min) {
                    second = red;
                } else {
                    second = min;
                    min = red;
                    jmin = j;
                }
            }
        }
        u[i] = min;
        if (second < BIG) {
            v[jmin] -= (second - min);
        }
        if (matches[jmin]) {
            rowsol[i] = -1;
            freeunassigned.push_back(i);
        } else {
            matches[jmin] = 1;
            rowsol[i] = jmin;
            colsol[jmin] = i;
        }
    }

    // The v-reduction above can make previously matched reduced costs negative
    // and can make u stale. Repair: recompute feasible duals from current v? 
    // v was only decreased, so reduced costs of non-chosen entries only increase
    // relative to the chosen column of that row... This is the standard JV reduction
    // and is known to be subtle. We'll verify feasibility after and fall back.

    // ---------- REDUCTION TRANSFER ----------
    int nfree = 0;
    std::vector<int> free_rows(n);
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) free_rows[nfree++] = i;
    }

    // Augmenting row reduction: 2 passes
    for (int loop = 0; loop < 2; ++loop) {
        int k = 0;
        int prevfree = nfree;
        nfree = 0;
        while (k < prevfree) {
            int i = free_rows[k++];
            const double* row = assigncost + (size_t)i * n;
            double umin = BIG, usubmin = BIG;
            int j1 = -1, j2 = -1;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        j2 = j1;
                        umin = h;
                        j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            double h = (usubmin < BIG && umin < BIG) ? (usubmin - umin) : 0.0;
            if (h > 0) {
                v[j1] -= h;
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            u[i] = umin;
            if (i0 >= 0) {
                if (h > 0) {
                    // transfer
                    free_rows[nfree++] = i0;
                    rowsol[i0] = -1;
                    rowsol[i] = j1;
                    colsol[j1] = i;
                } else {
                    free_rows[nfree++] = i;
                }
            } else {
                rowsol[i] = j1;
                colsol[j1] = i;
            }
        }
    }

    // ---------- AUGMENTATION ----------
    std::vector<char> inpath(n);
    for (int f = 0; f < nfree; ++f) {
