                            }
                            collist[k] = collist[up];
                            collist[up] = j;
                            ++up;
                        }
                    }
                }
            }
        } while (!unassigned_found);

        // update duals
        for (int k = 0; k < last; ++k) {
            int j = collist[k];
            v[j] += d[j] - min;
        }
        // augment
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            j = jnext;
            if (i == freerow) break;
        }
    }
    return 0;
}
