// Dense min-cost assignment via successive shortest paths.
// Safe init: u_i = min_j c_ij, v = 0, greedy tight matching.
// Augmentation uses JV-style dynamic threshold so many columns are priced per scan.
#include <cstdint>
#include <algorithm>
#include <vector>

extern "C" int lapjv(int n, const double* __restrict cost, int* __restrict rowsol) {
    const double INF = 1e100;
    std::vector<double> u(n), v(n, 0.0), d(n);
    std::vector<int> colsol(n, -1), pred(n), collist(n), free_rows;
    free_rows.reserve(n);

    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        double m = row[0];
        int jmin = 0;
        for (int j = 1; j < n; ++j) {
            double c = row[j];
            if (c < m) { m = c; jmin = j; }
        }
        u[i] = m;
        if (colsol[jmin] < 0) {
            colsol[jmin] = i;
            rowsol[i] = jmin;
        } else {
            rowsol[i] = -1;
            free_rows.push_back(i);
        }
    }

    const int nfree = (int)free_rows.size();
    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        const double* frow = cost + (size_t)freerow * n;
        double uf = u[freerow];
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - uf - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0;
        int endofpath = -1;
        double mind = 0;
        int last = 0;
        bool found = false;

        while (!found) {
            if (up == low) {
                last = low;
                mind = d[collist[up]];
                ++up;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double h = d[j];
                    if (h <= mind) {
                        if (h < mind) {
                            up = low;
                            mind = h;
                        }
                        collist[k] = collist[up];
                        collist[up++] = j;
                    }
                }
                for (int k = low; k < up; ++k) {
                    if (colsol[collist[k]] < 0) {
                        endofpath = collist[k];
                        found = true;
                        break;
                    }
                }
            }
            if (found) break;
            int j1 = collist[low++];
            int i = colsol[j1];
            const double* row = cost + (size_t)i * n;
            double cred = row[j1] - v[j1];
            double ui = u[i];
            // reduced candidate: mind + (c_ij - u_i - v_j) - (c_ij1 - u_i - v_j1)
            // = mind + c_ij - v_j - cred
            for (int k = up; k < n; ++k) {
                int j = collist[k];
                double h = row[j] - v[j] - cred + mind;
                if (h < d[j]) {
                    pred[j] = i;
                    d[j] = h;
                    if (h == mind) {
                        if (colsol[j] < 0) {
                            endofpath = j;
                            found = true;
                        }
                        collist[k] = collist[up];
                        collist[up++] = j;
                    }
                }
            }
        }

        // dual update: scanned-but-not-ready columns are collist[0:last)
        for (int k = 0; k < last; ++k) {
            int j = collist[k];
            double delta = d[j] - mind;
            v[j] += delta;
            u[colsol[j]] -= delta;
        }
        u[freerow] += mind;

        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nj = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = nj;
        }
    }
    return 0;
}
