// Classic Jonker-Volgenant (column reduction + reduction transfer + ARR + augment).
#include <cstdint>
#include <algorithm>
#include <vector>
#include <cstring>

extern "C" int lapjv(int n, const double* __restrict cost, int* __restrict rowsol) {
    const double BIG = 1e100;
    std::vector<int> colsol(n, -1), matches(n, 0), free_rows(n), pred(n), collist(n);
    std::vector<double> u(n, 0.0), v(n, 0.0), d(n);

    // COLUMN REDUCTION: for each column, assign to the row with smallest cost if that row is free.
    for (int j = n - 1; j >= 0; --j) {
        double minc = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minc) { minc = c; imin = i; }
        }
        v[j] = minc;
        if (++matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }

    // REDUCTION TRANSFER
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (matches[i] == 0) {
            free_rows[numfree++] = i;
        } else if (matches[i] == 1) {
            int j1 = rowsol[i];
            double minc = BIG;
            const double* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) if (j != j1) {
                double h = row[j] - v[j];
                if (h < minc) minc = h;
            }
            v[j1] -= minc;
        } else {
            rowsol[i] = -1; // matched more than once in the count, but only one assignment stored; others unassigned
        }
    }
    // rows with matches>1: one column was assigned (the last ++ that hit 1? NO).
    // Look at the loop: we only assign when matches becomes 1. Subsequent columns that also
    // prefer this row are left unassigned (colsol=-1) and the row keeps its first assignment.
    // So matches[i]>1 means the row IS assigned, and extra columns are free (colsol=-1).
    // Those free columns will be picked up during augmentation. Rows are all either assigned or free.
    // BUG: I set rowsol[i]=-1 for matches>1 which DESTROYS the valid assignment. Fix: don't.
    // We'll recompute free rows from colsol instead below. Rebuild properly.

    // Re-run assignment bookkeeping correctly by recomputing from the first loop's intent.
    // Easiest: redo column reduction cleanly.
    std::fill(matches.begin(), matches.end(), 0);
    std::fill(colsol.begin(), colsol.end(), -1);
    std::fill(v.begin(), v.end(), 0.0);
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    for (int j = n - 1; j >= 0; --j) {
        double minc = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minc) { minc = c; imin = i; }
        }
        v[j] = minc;
        if (matches[imin] == 0) {
            matches[imin] = 1;
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }
    numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (matches[i] == 0) free_rows[numfree++] = i;
        else {
            int j1 = rowsol[i];
            double minc = BIG;
            const double* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) if (j != j1) {
                double h = row[j] - v[j];
                if (h < minc) minc = h;
            }
            if (minc < BIG) v[j1] -= minc;
            u[i] = cost[(size_t)i * n + j1] - v[j1];
        }
    }

    // AUGMENTING ROW REDUCTION (2 loops)
    for (int loop = 0; loop < 2; ++loop) {
        int k = 0, prv = numfree;
        numfree = 0;
        while (k < prv) {
            int i = free_rows[k++];
            const double* row = cost + (size_t)i * n;
            double umin = BIG, usub = BIG;
            int j1 = 0, j2 = 0;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; j2 = j1; umin = h; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0) { j1 = j2; i0 = colsol[j1]; }
            if (i0 >= 0) {
                if (umin < usub) free_rows[numfree++] = i0;
                else free_rows[numfree++] = i;
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0 && umin < usub) rowsol[i0] = -1;
        }
    }

    // store how many free for the caller via u[0] hack? we'll just augment.
    // AUGMENT
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        const double* frow = cost + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0, last = 0, endofpath = -1;
        double mind = 0;
        bool found = false;
        while (!found) {
            if (up == low) {
                last = low;
                mind = d[collist[up]];
                ++up;
                for (int kk = up; kk < n; ++kk) {
                    int j = collist[kk];
                    double h = d[j];
                    if (h <= mind) {
                        if (h < mind) { up = low; mind = h; }
                        collist[kk] = collist[up];
                        collist[up++] = j;
                    }
                }
                for (int kk = low; kk < up; ++kk) if (colsol[collist[kk]] < 0) {
                    endofpath = collist[kk]; found = true; break;
                }
            }
            if (found) break;
            int j1 = collist[low++];
            int i = colsol[j1];
            const double* row = cost + (size_t)i * n;
            double cred = row[j1] - v[j1];
            for (int kk = up; kk < n; ++kk) {
                int j = collist[kk];
                double h = row[j] - v[j] - cred + mind;
                if (h < d[j]) {
                    pred[j] = i;
                    d[j] = h;
                    if (h == mind) {
                        if (colsol[j] < 0) { endofpath = j; found = true; }
                        collist[kk] = collist[up];
                        collist[up++] = j;
                    }
                }
