// Bipartite transportation network simplex for the assignment problem.
// Nodes: rows 0..n-1 (supply 1), columns n..2n-1 (supply -1).
// Artificial root = 2n.
// Initial basis: root connected to every node.
//   root -> row i : flow 1, cost 0 (root supplies the row)
//   col j -> root : flow 1, cost 0 (column ships demand to root)
// Potentials: pi[root]=0, pi[row]=0, pi[col]=0.
// Entering arc: most violated row->col reduced cost c_ij - pi_row + pi_col? 
//   reduced cost of arc row->col is c_ij - pi[row] + pi[col] if we use
//   convention cost' = c - pi_tail + pi_head, and we want cost' >= 0 for optimality
//   (minimization). Enter if c_ij - pi[i] + pi[j+n] < 0.
//
// Tree stored as parent/child/sibling with direction.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <cstdio>

struct Node {
    int parent;
    int child;     // first child
    int sibling;   // next sibling
    int size;      // subtree size
    int dir;       // +1 if arc parent->this is oriented parent to node, -1 if node to parent
    double pi;
    double flow;   // flow on arc between parent and this (always stored positive in the parent->? direction of the basic arc)
};

extern "C" int lapjv(int n, const double* cost, int* rowsol) {
    const int N = 2 * n + 1;
    const int ROOT = 2 * n;
    std::vector<Node> T(N);
    for (int i = 0; i < N; ++i) {
        T[i].parent = -1; T[i].child = -1; T[i].sibling = -1;
        T[i].size = 1; T[i].dir = 0; T[i].pi = 0; T[i].flow = 0;
    }
    // link all rows and columns as children of root
    // rows: root -> row, flow 1
    // cols: col -> root, flow 1, so dir = -1 (arc points toward parent)
    int prev = -1;
    for (int i = 0; i < n; ++i) {
        T[i].parent = ROOT;
        T[i].dir = +1;
        T[i].flow = 1;
        T[i].sibling = prev;
        prev = i;
    }
    for (int j = 0; j < n; ++j) {
        int node = n + j;
        T[node].parent = ROOT;
        T[node].dir = -1; // arc node -> parent
        T[node].flow = 1;
        T[node].sibling = prev;
        prev = node;
    }
    T[ROOT].child = prev;
    T[ROOT].size = N;
    T[ROOT].parent = -1;

    auto reduced = [&](int i, int j) -> double {
        // arc i -> n+j
        return cost[(size_t)i * n + j] - T[i].pi + T[n + j].pi;
    };

    // pivot helpers
    auto update_subtree_pi = [&](int start, double delta, auto&& self) -> void {
        T[start].pi += delta;
        for (int c = T[start].child; c >= 0; c = T[c].sibling) self(c, delta, self);
    };
    auto update_size_up = [&](int node, int delta) {
        while (node >= 0) { T[node].size += delta; node = T[node].parent; }
    };

    // detach node from its parent
    auto detach = [&](int node) {
        int p = T[node].parent;
        int prevs = -1;
        int c = T[p].child;
        while (c != node) { prevs = c; c = T[c].sibling; }
        if (prevs < 0) T[p].child = T[node].sibling;
        else T[prevs].sibling = T[node].sibling;
