        for (int x = u; x != apex; x = T[x].parent) {
            if (T[x].dir == +1) T[x].flow -= delta;
            else T[x].flow += delta;
        }
        for (int x = v; x != apex; x = T[x].parent) {
            if (T[x].dir == -1) T[x].flow -= delta;
