// Column-reduction init (same as jv3) then batch Dijkstra augmentations.
// Each augmentation is an independent Dijkstra if we don't update duals between them... 
// Dual updates ARE required for reduced-cost nonnegativity of subsequent Dijkstras.
// So batching independent Dijkstras is incorrect unless we recompute.
// Instead: run several augmentations but share the column scan by processing one Dijkstra
// with a heap (O(n^2) still) — not helpful.
//
// New idea: auction algorithm, which parallelizes and is very fast for assignment,
// then if the assignment doesn't match emd, fall back. First test if auction matches emd
// and how fast.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdio>

extern "C" int auction(int n, const double* cost, int* rowsol, double eps_final) {
    std::vector<double> price(n, 0.0);
    std::vector<int> col_of_row(n, -1);
    std::vector<int> row_of_col(n, -1);
    double eps = 1.0;
    const double *c = cost;
    int iter_guard = 0;
    while (eps >= eps_final * 0.5) {
        std::fill(col_of_row.begin(), col_of_row.end(), -1);
        std::fill(row_of_col.begin(), row_of_col.end(), -1);
        int unassigned = n;
        int guard = 0;
        while (unassigned && guard < n * n) {
            ++guard; ++iter_guard;
            for (int i = 0; i < n && unassigned; ++i) {
                if (col_of_row[i] >= 0) continue;
                const double* row = c + (size_t)i * n;
                // best and second best value = -cost - price? Auction maximizes value.
                // value_ij = -cost_ij. Bid on object j maximizing -c_ij - price_j.
                double best = -1e300, second = -1e300;
                int jbest = 0;
                for (int j = 0; j < n; ++j) {
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                }
                double bid = price[jbest] + (best - second) + eps;
                // assign
                int prev = row_of_col[jbest];
                if (prev >= 0) {
                    col_of_row[prev] = -1;
                } else {
                    --unassigned;
                }
                row_of_col[jbest] = i;
                col_of_row[i] = jbest;
                price[jbest] = bid;
            }
        }
        if (unassigned) {
            // failed to assign at this eps
            eps *= 0.25;
            continue;
        }
        eps *= 0.25;
    }
