// Gauss-Seidel auction on maximization of -cost.
// eps scaled externally: caller passes costs already scaled? we scale internally by working
// on cost directly.
extern "C" int auction(int n, const double* __restrict cost, int* __restrict rowsol, double eps_final) {
    std::vector<double> price(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1);
    std::vector<int> unassigned(n);
    double eps = 0.1; // costs are ~O(1)
    int total_scans = 0;
    while (true) {
        for (int i = 0; i < n; ++i) { col_of_row[i] = -1; row_of_col[i] = -1; unassigned[i] = i; }
        int nfree = n;
        int guard = 0;
        const int guardmax = n * 8 + 1000;
        while (nfree > 0 && guard < guardmax) {
            ++guard;
            ++total_scans;
            int new_nfree = 0;
            for (int t = 0; t < nfree; ++t) {
                int i = unassigned[t];
                if (col_of_row[i] >= 0) continue;
                const double* row = cost + (size_t)i * n;
                double best = -1e300, second = -1e300;
                int jbest = 0;
                for (int j = 0; j < n; ++j) {
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                }
                double bid = price[jbest] + (best - second) + eps;
                int prev = row_of_col[jbest];
                if (prev >= 0) {
                    col_of_row[prev] = -1;
                    unassigned[new_nfree++] = prev;
                }
                row_of_col[jbest] = i;
                col_of_row[i] = jbest;
                price[jbest] = bid;
            }
            nfree = new_nfree;
        }
        if (nfree > 0) {
            // didn't finish; shrink eps and retry (prices kept — actually reset prices to be safe)
            eps *= 0.25;
            if (eps < eps_final) break;
            std::fill(price.begin(), price.end(), 0.0);
            continue;
        }
        if (eps <= eps_final) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
        // keep prices (warm) but reset assignment for next phase? Bertsekas keeps prices and continues
        // with unassigned empty — assignment remains epsilon-optimal. For next phase, everyone is assigned.
        // We should NOT reset assignment; instead run a phase that only reassigns if beneficial.
        // Simpler: keep going with fresh assignment but warm prices. That's what we do if we loop.
        // Currently assignment is complete and we loop to while(true) which RESETS assignment. That's OK
        // with warm prices — next phase starts unassigned but prices carry information.
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return total_scans;
}
