#include <cstdint>
#include <vector>
#include <algorithm>
#include <cstring>
#include <thread>
#include <atomic>

// Jacobi auction: all unassigned persons bid simultaneously based on the same prices,
// then the highest bidder for each object wins.
struct Bid {
    double val;      // -cost - price of best
    double second;
    int jbest;
    int person;
};

static void scan_range(int n, const double* cost, const double* price,
                       const int* unassigned, int begin, int end,
                       Bid* bids) {
    for (int t = begin; t < end; ++t) {
        int i = unassigned[t];
        const double* row = cost + (size_t)i * n;
        double best = -1e300, second = -1e300;
        int jbest = 0;
        for (int j = 0; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > best) { second = best; best = val; jbest = j; }
            else if (val > second) second = val;
        }
        bids[t].val = best;
        bids[t].second = second;
        bids[t].jbest = jbest;
        bids[t].person = i;
    }
}

extern "C" int auction(int n, const double* cost, int* rowsol, double eps_final, int nthreads) {
    std::vector<double> price(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1);
    std::vector<int> unassigned(n);
    std::vector<Bid> bids(n);
    std::vector<int> best_bidder(n);
    std::vector<double> best_bid_improve(n);
    if (nthreads < 1) nthreads = 1;
    double eps = 0.1;
    int scans = 0;
    while (true) {
        for (int i = 0; i < n; ++i) {
            col_of_row[i] = -1;
            row_of_col[i] = -1;
            unassigned[i] = i;
        }
        int nfree = n;
        int guard = 0;
        while (nfree > 0 && guard < n * 20) {
            ++guard; ++scans;
            // parallel scan
            int T = nthreads;
            if (nfree < 32) T = 1;
            if (T == 1) {
                scan_range(n, cost, price.data(), unassigned.data(), 0, nfree, bids.data());
            } else {
                std::vector<std::thread> th;
                int chunk = (nfree + T - 1) / T;
                for (int t = 0; t < T; ++t) {
                    int b = t * chunk, e = std::min(nfree, b + chunk);
                    if (b >= e) break;
                    th.emplace_back(scan_range, n, cost, price.data(), unassigned.data(), b, e, bids.data());
                }
                for (auto& x : th) x.join();
            }
            std::fill(best_bidder.begin(), best_bidder.end(), -1);
            std::fill(best_bid_improve.begin(), best_bid_improve.end(), -1e300);
            for (int t = 0; t < nfree; ++t) {
                int j = bids[t].jbest;
                double improve = bids[t].val - bids[t].second; // bid increment before eps
                if (improve > best_bid_improve[j]) {
                    best_bid_improve[j] = improve;
                    best_bidder[j] = t;
                }
            }
            int new_nfree = 0;
            for (int j = 0; j < n; ++j) {
                int t = best_bidder[j];
                if (t < 0) continue;
                int i = bids[t].person;
                double bid = price[j] + best_bid_improve[j] + eps;
                int prev = row_of_col[j];
                if (prev >= 0 && prev != i) {
                    col_of_row[prev] = -1;
                    unassigned[new_nfree++] = prev;
                }
                if (col_of_row[i] < 0) {
                    // was unassigned, now assigned: don't add to unassigned
                }
                row_of_col[j] = i;
                col_of_row[i] = j;
                price[j] = bid;
            }
            // anyone still unassigned
            for (int t = 0; t < nfree; ++t) {
                int i = bids[t].person;
                if (col_of_row[i] < 0) unassigned[new_nfree++] = i;
            }
            nfree = new_nfree;
        }
        if (nfree > 0) {
            eps *= 0.25;
            std::fill(price.begin(), price.end(), 0.0);
            if (eps < eps_final * 0.1) break;
            continue;
        }
        if (eps <= eps_final) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return scans;
}
