    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int jmin = 0; double m = row[0];
        for (int j = 1; j < n; ++j) if (row[j] < m) { m = row[j]; jmin = j; }
        if (col_match[jmin] < 0) { row_match[i] = jmin; col_match[jmin] = i; }
    }
    // potentials: pi_row = 0, pi_col = -cost of matched edge so reduced cost 0: 
    // rc = c - pi_row + pi_col = 0 => pi_col = -c + pi_row
    for (int j = 0; j < n; ++j) if (col_match[j] >= 0) {
        int i = col_match[j];
        pi[n + j] = -cost[(size_t)i * n + j];
    }
    // Tree: root = row 0.
    // Connect every matched column as child of its row, flow 1 from row to col.
    // Unmatched columns: attach to row 0 with flow 0.
    // Unmatched rows: attach to column 0 (or any existing col) with flow 0.
    auto link_child = [&](int node, int par) {
        parent[node] = par;
        sibling[node] = child[par];
        child[par] = node;
    };
