    std::vector<int> stack = {0};
    std::vector<int> state(N, 0);
    while (!stack.empty()) {
        int u = stack.back();
        if (state[u] == 0) {
            state[u] = 1;
            for (int c = child[u]; c >= 0; c = sibling[c]) stack.push_back(c);
        } else {
            stack.pop_back();
            int s = 1;
            for (int c = child[u]; c >= 0; c = sibling[c]) s += size[c];
