// Optimized JV: column reduction + reduction transfer + ARR + threshold augmentation.
// Inner loop written for clang vectorization. Cost is row-major; augmentation scans rows.
#include <cstdint>
#include <algorithm>
#include <vector>
#include <cstring>

extern "C" int lapjv(int n, const double* __restrict cost, int* __restrict rowsol) {
    const double BIG = 1e100;
    std::vector<int> colsol(n, -1), matches(n, 0), free_rows(n), pred(n), collist(n);
    std::vector<double> v(n), d(n);

    // ---- column reduction (strided, unavoidable) ----
    for (int j = n - 1; j >= 0; --j) {
        const double* colp = cost + j;
        double minc = colp[0];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = colp[(size_t)i * n];
            if (c < minc) { minc = c; imin = i; }
        }
        v[j] = minc;
        if (matches[imin] == 0) {
            matches[imin] = 1;
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }
    for (int i = 0; i < n; ++i) if (!matches[i]) rowsol[i] = -1;

    int numfree = 0;
    // ---- reduction transfer (contiguous) ----
    for (int i = 0; i < n; ++i) {
        if (matches[i] == 0) {
            free_rows[numfree++] = i;
            continue;
        }
        int j1 = rowsol[i];
        const double* row = cost + (size_t)i * n;
        double minc = BIG;
        for (int j = 0; j < n; ++j) {
            if (j == j1) continue;
            double h = row[j] - v[j];
            if (h < minc) minc = h;
        }
        v[j1] -= minc;
    }

    // ---- augmenting row reduction, 2 passes ----
    for (int loop = 0; loop < 2; ++loop) {
        int k = 0, prv = numfree;
        numfree = 0;
