#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
#include <cstdio>

// Recover 2D coords from Euclidean distance matrix, build kNN, run JV on the sparse graph
// represented as per-row neighbor lists. If the resulting assignment has negative reduced
// cost outside the graph, return failure (caller falls back).
//
// Coord recovery:
//   A = M^2
//   B = center(A)
//   B = -2 X Y^T with X, Y centered coordinates (n x 2)
//   SVD of B: B = U S Vh, take top 2.
//   Set X = U[:, :2] * sqrt(S[:2]/2), Y = -V[:, :2] * sqrt(S[:2]/2)
//   Then ||Xi - Yj||^2 = ||Xi||^2 + ||Yj||^2 - 2 Xi·Yj = ||Xi||^2+||Yj||^2 + B_ij
//   and ||Si-Tj||^2 = A_ij = ||Si||^2+||Tj||^2 - 2 Si·Tj, with B_ij = -2 Si_c · Tj_c.
//   Distances between recovered X,Y equal original distances.

extern "C" {

struct Scratch {
    int n;
    std::vector<double> A, B, X, Y; // A,B n*n, X,Y n*2
    std::vector<int> neigh; // n * k
    std::vector<double> ndist;
    int k;
};

// power iteration SVD for top 2 of symmetric-ish rectangular B (n x n), B is centered Gram.
// We compute top 2 right singular vectors by iterating B^T B which is n x n — too slow (n^2 per multiply, few iters: ~10*n^2 = OK, similar to one pass).
// 20 matvecs of n^2 is 20x a scan. Too slow if many. Use randomized: 2 gaussian vectors, 2 matvecs, QR, small SVD.
// B is n x n. One matvec is n^2. 4 matvecs = 4 scans. Acceptable if total stays under 5ms? 600^2*8 = 2.9MB, 4 scans ~1ms. OK.

static void randomized_factors(int n, const double* B, double* X, double* Y) {
    // Gaussian-ish deterministic vectors
    std::vector<double> omega(n * 2), Yp(n * 2), Z(n * 2), Q(n * 2);
    for (int j = 0; j < 2; ++j) {
        uint64_t s = 0x9e3779b97f4a7c15ULL * (j + 1);
        for (int i = 0; i < n; ++i) {
            s = s * 6364136223846793005ULL + 1;
            // uniform [-1,1]
            omega[i + j * n] = ((s >> 33) / double(1ULL << 31)) * 2.0 - 1.0;
        }
    }
    auto matvec_right = [&](const double* V, double* Out) {
        // Out = B * V, V is n x 2
        for (int i = 0; i < n; ++i) {
            const double* row = B + (size_t)i * n;
            double a0 = 0, a1 = 0;
            const double* v0 = V;
            const double* v1 = V + n;
            for (int j = 0; j < n; ++j) {
                double b = row[j];
                a0 += b * v0[j];
                a1 += b * v1[j];
            }
            Out[i] = a0;
            Out[i + n] = a1;
        }
    };
    // Y = B * omega
    matvec_right(omega.data(), Yp.data());
    // QR of Y (n x 2)
    // modified gram-schmidt
    double nrm0 = 0;
    for (int i = 0; i < n; ++i) nrm0 += Yp[i] * Yp[i];
    nrm0 = std::sqrt(nrm0);
    for (int i = 0; i < n; ++i) Q[i] = Yp[i] / nrm0;
    double dot = 0;
    for (int i = 0; i < n; ++i) dot += Yp[i + n] * Q[i];
    double nrm1 = 0;
    for (int i = 0; i < n; ++i) {
        double w = Yp[i + n] - dot * Q[i];
        Q[i + n] = w;
        nrm1 += w * w;
    }
    nrm1 = std::sqrt(nrm1);
    for (int i = 0; i < n; ++i) Q[i + n] /= nrm1;
    // Z = B^T Q = (Q^T B)^T so compute B^T Q via matvec on B^T: row-dot is col of B.
    // B is symmetric! centered squared-distance matrix of a single set isn't, but
    // B_ij = A_ij - rowmean_i - colmean_j + grand, A not symmetric, B not symmetric.
    // Compute C = Q^T B (2 x n) by two row-dots: C[a, j] = sum_i Q[i,a] * B[i,j]
    std::vector<double> C(2 * n, 0.0);
    for (int i = 0; i < n; ++i) {
        const double* row = B + (size_t)i * n;
        double q0 = Q[i], q1 = Q[i + n];
        double* c0 = C.data();
        double* c1 = C.data() + n;
        for (int j = 0; j < n; ++j) {
            double b = row[j];
            c0[j] += q0 * b;
            c1[j] += q1 * b;
        }
    }
    // small SVD of C which is 2 x n: C = U_small S Vh, Vh is 2 x n (right vectors in R^n)
    // Form C C^T (2x2)
    double a = 0, b = 0, c = 0;
    for (int j = 0; j < n; ++j) {
        double x = C[j], y = C[n + j];
        a += x * x; b += x * y; c += y * y;
    }
    // eig of [[a,b],[b,c]]
    double tr = a + c, det = a * c - b * b;
    double disc = std::sqrt(std::max(0.0, tr * tr - 4 * det));
    double l1 = 0.5 * (tr + disc), l2 = 0.5 * (tr - disc);
    auto eigvec = [&](double l, double& x, double& y) {
        // (a-l) x + b y = 0
        if (std::abs(b) > std::abs(a - l)) { x = b; y = -(a - l); }
        else { x = -(c - l); y = b; }
        double nr = std::sqrt(x * x + y * y) + 1e-30;
        x /= nr; y /= nr;
    };
    double u00, u10, u01, u11;
    eigvec(l1, u00, u10);
    eigvec(l2, u01, u11);
    double s1 = std::sqrt(std::max(0.0, l1)), s2 = std::sqrt(std::max(0.0, l2));
    // Vh rows: (1/s) * u^T * C
    // X_coords (n x 2) = Q * U_small * sqrt(S/2)
    // Y_coords (n x 2) = - V * sqrt(S/2), V columns = right singular vectors = Vh rows
    double f1 = std::sqrt(s1 / 2.0), f2 = std::sqrt(s2 / 2.0);
    for (int i = 0; i < n; ++i) {
        double q0 = Q[i], q1 = Q[i + n];
        // Q * U = [q0, q1] * [[u00, u01],[u10, u11]]
        X[i * 2]     = (q0 * u00 + q1 * u10) * f1;
        X[i * 2 + 1] = (q0 * u01 + q1 * u11) * f2;
    }
    for (int j = 0; j < n; ++j) {
        double c0 = C[j], c1 = C[n + j];
        // Vh row0 = (u00 * c0_row + u10 * c1_row) / s1
        double v0 = (u00 * c0 + u10 * c1) / (s1 + 1e-30);
        double v1 = (u01 * c0 + u11 * c1) / (s2 + 1e-30);
        Y[j * 2]     = -v0 * f1;
        Y[j * 2 + 1] = -v1 * f2;
    }
}

// Build kNN of Y for each X using a grid hash.
static void build_knn(int n, const double* X, const double* Y, int k,
                      std::vector<int>& neigh, std::vector<double>& ndist) {
    neigh.assign(n * k, 0);
    ndist.assign(n * k, 1e100);
    // grid
    const int G = 24;
    std::vector<int> counts(G * G, 0), starts(G * G + 1, 0);
    std::vector<int> cell(n);
    auto cell_of = [&](double x, double y) {
        int ix = std::min(G - 1, std::max(0, (int)(x * G)));
        int iy = std::min(G - 1, std::max(0, (int)(y * G)));
        return iy * G + ix;
    };
    // Y may be slightly outside [0,1] due to centering recovery — shift/scale later if needed.
    // Use raw coords; find bbox
    double minx = 1e300, miny = 1e300, maxx = -1e300, maxy = -1e300;
    for (int j = 0; j < n; ++j) {
        minx = std::min(minx, Y[j*2]); miny = std::min(miny, Y[j*2+1]);
        maxx = std::max(maxx, Y[j*2]); maxy = std::max(maxy, Y[j*2+1]);
    }
    double sx = maxx - minx + 1e-12, sy = maxy - miny + 1e-12;
    for (int j = 0; j < n; ++j) {
        int ix = std::min(G - 1, std::max(0, (int)((Y[j*2] - minx) / sx * G)));
        int iy = std::min(G - 1, std::max(0, (int)((Y[j*2+1] - miny) / sy * G)));
        cell[j] = iy * G + ix;
        counts[cell[j]]++;
    }
    for (int i = 0; i < G * G; ++i) starts[i + 1] = starts[i] + counts[i];
    std::vector<int> cursor = starts, buckets(n);
    for (int j = 0; j < n; ++j) buckets[cursor[cell[j]]++] = j;

    auto insert = [&](int i, int j, double d2) {
        // insert into sorted neigh list of size k (largest at end)
        double* dist = &ndist[i * k];
        int* nb = &neigh[i * k];
        if (d2 >= dist[k - 1]) return;
        int p = k - 1;
        while (p > 0 && d2 < dist[p - 1]) {
            dist[p] = dist[p - 1];
            nb[p] = nb[p - 1];
            --p;
        }
        dist[p] = d2;
        nb[p] = j;
    };

    for (int i = 0; i < n; ++i) {
        double x = X[i*2], y = X[i*2+1];
        int ix = std::min(G - 1, std::max(0, (int)((x - minx) / sx * G)));
        int iy = std::min(G - 1, std::max(0, (int)((y - miny) / sy * G)));
        // expand rings until we have k candidates; then verify radius
        int found = 0;
        int rad = 1;
        while (found < k && rad < G) {
            int x0 = std::max(0, ix - rad), x1 = std::min(G - 1, ix + rad);
            int y0 = std::max(0, iy - rad), y1 = std::min(G - 1, iy + rad);
            for (int yy = y0; yy <= y1; ++yy) {
                for (int xx = x0; xx <= x1; ++xx) {
                    if (rad > 1 && xx > x0 && xx < x1 && yy > y0 && yy < y1) continue;
                    int c = yy * G + xx;
                    for (int p = starts[c]; p < starts[c + 1]; ++p) {
                        int j = buckets[p];
                        double dx = x - Y[j*2], dy = y - Y[j*2+1];
                        insert(i, j, dx * dx + dy * dy);
                        ++found;
                    }
                }
            }
            ++rad;
        }
        // one more ring to be safe relative to kth distance
        double r2 = ndist[i * k + k - 1];
        int x0 = std::max(0, ix - rad), x1 = std::min(G - 1, ix + rad);
        int y0 = std::max(0, iy - rad), y1 = std::min(G - 1, iy + rad);
        for (int yy = y0; yy <= y1; ++yy) for (int xx = x0; xx <= x1; ++xx) {
            if (std::max(std::abs(xx - ix), std::abs(yy - iy)) < rad) continue;
            int c = yy * G + xx;
            for (int p = starts[c]; p < starts[c + 1]; ++p) {
                int j = buckets[p];
                double dx = x - Y[j*2], dy = y - Y[j*2+1];
                double d2 = dx*dx+dy*dy;
                if (d2 < r2) insert(i, j, d2);
