// returns 0 on success (assignment in rowsol), 1 if should fall back
int lap_geom(int n, const double* cost, int* rowsol, int k) {
    std::vector<double> A((size_t)n * n), B((size_t)n * n), X(n * 2), Y(n * 2);
    // A = M^2, row means, col means
    std::vector<double> rowmean(n, 0.0), colmean(n, 0.0);
    double grand = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        double* a = A.data() + (size_t)i * n;
        double s = 0;
        for (int j = 0; j < n; ++j) {
            double m = row[j];
            double m2 = m * m;
            a[j] = m2;
            s += m2;
            colmean[j] += m2;
        }
        rowmean[i] = s / n;
        grand += s;
    }
    grand /= (double)n * n;
    for (int j = 0; j < n; ++j) colmean[j] /= n;
    for (int i = 0; i < n; ++i) {
        double* b = B.data() + (size_t)i * n;
        const double* a = A.data() + (size_t)i * n;
        double rm = rowmean[i];
        for (int j = 0; j < n; ++j) b[j] = a[j] - rm - colmean[j] + grand;
    }
    randomized_factors(n, B.data(), X.data(), Y.data());
    std::vector<int> neigh;
    std::vector<double> ndist;
    build_knn(n, X.data(), Y.data(), k, neigh, ndist);

    // verify kNN against true cost for a sample? skip
    // Run assignment restricted to neigh using JV-like successive shortest paths on sparse graph.
    // For correctness test first: just check whether true emd assignment is inside kNN.
    return 2; // signal "built"
}

