// Network simplex for the balanced assignment problem.
// Nodes: rows 0..n-1, cols n..2n-1. Root = row 0.
// Tree: parent[], sibling[], child[], subtree size, potential pi[],
// flow_rc[] = row->col flow on the edge connecting node to its parent (0 or 1).
//
// Reduced cost of arc row i -> col j: c_ij - pi[i] + pi[n+j]. Optimal when all >= -eps.
//
// Initialization: identity-like greedy matching, columns hung off their matched rows,
// unmatched columns hung off row 0 with flow 0, unmatched rows hung off column 0 with flow 0.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdio>
#include <cstring>

extern "C" int lapjv(int n, const double* cost, int* rowsol) {
    const int N = 2 * n;
    const double EPS = 1e-9;
    std::vector<int> parent(N, -1), child(N, -1), sibling(N, -1), sz(N, 1);
    std::vector<double> pi(N, 0.0), flow(N, 0.0); // flow[node] = row->col flow on edge to parent

    std::vector<int> rmatch(n, -1), cmatch(n, -1);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int jb = 0; double mb = row[0];
        for (int j = 1; j < n; ++j) if (row[j] < mb) { mb = row[j]; jb = j; }
