        // Equivalent tree circulation goes from V up to apex and from apex down to U,
        // i.e. on V-side edges direction is child->parent, on U-side parent->child.
        // flow[node] is row->col flow on edge (node, parent).
        // Residual when we need to push against row->col (i.e. cycle direction is col->row): residual = flow.
        //
        // U side: cycle direction parent -> child.
        //   edge (child=node, parent): if node is col (parent is row): parent->child is row->col. flow increases. residual inf.
        //   if node is row (parent is col): parent->child is col->row. flow decreases. residual = flow[node].
        // V side: cycle direction child -> parent.
        //   if node is col (parent row): child->parent is col->row. residual = flow[node].
        //   if node is row (parent col): child->parent is row->col. flow increases. residual inf.
