        for (int x = U; x != apex; x = parent[x]) {
            if (x < n) flow[x] -= delta;      // decreasing
            else flow[x] += delta;            // increasing (parent row -> child col)
        }
        for (int x = V; x != apex; x = parent[x]) {
            if (x >= n) flow[x] -= delta;
            else flow[x] += delta;
        }

        // Pivot tree: remove leave edge, reverse path so the entering-arc endpoint
        // inside the cut subtree becomes the subtree root, attach it to the outside endpoint.
        int old_parent_of_leave = parent[leave];
        detach(leave);
        // which entering endpoint is in leave's subtree?
        // After detach, parent[leave] still equals old parent, so walking hits leave then escapes.
        bool u_inside = false;
        for (int x = U; x >= 0; x = parent[x]) {
            if (x == leave) { u_inside = true; break; }
            if (x == apex) break;
        }
        int inside = u_inside ? U : V;
        int outside = u_inside ? V : U;

        // Reverse parent pointers from `inside` up to `leave` so inside becomes root of this subtree.
        // Also fix flow and child lists along the reversed path.
        // Path nodes: inside, p1, p2, ..., leave. After reverse: leave's descendants stay,
