                flow[cur] = f; // keep until we reassign
                if (cur == leave) break;
                prev = cur;
                cur = p;
            }
        }
        // The reversal above set parent pointers backward (cur.parent = old child) but child lists and flow
        // are wrong. Rebuild the reversed chain explicitly.
        // Recover path first — TOO LATE, parent pointers already overwritten.
        std::fprintf(stderr, "pivot %d delta %g leave %d inside %d — reversal incomplete, abort\n", pivots, delta, leave, inside);
        return 4;
    }
    std::fprintf(stderr, "optimal in %d pivots\n", pivots);
    // extract matching: columns with flow 1 whose parent is a row, or rows with flow 1 whose parent is a col
    std::fill(rowsol, rowsol + n, -1);
    for (int node = 1; node < N; ++node) {
        if (flow[node] > 0.5) {
            int a = node, b = parent[node];
            int row = a < n ? a : b;
            int col = a < n ? b - n : a - n;
            rowsol[row] = col;
        }
    }
    return 0;
}
