        for (int j = 1; j < n; ++j) if (row[j] < mb) { mb = row[j]; jb = j; }
        if (cmatch[jb] < 0) { rmatch[i] = jb; cmatch[jb] = i; }
    }
    auto add_child = [&](int node, int par) {
        parent[node] = par;
        sibling[node] = child[par];
        child[par] = node;
    };
    for (int j = 0; j < n; ++j) {
        int col = n + j;
