            int i = cmatch[j];
            add_child(col, i);
            flow[col] = 1.0;
            pi[col] = pi[i] - cost[(size_t)i * n + j];
        } else {
            add_child(col, 0);
            flow[col] = 0.0;
            pi[col] = pi[0] - cost[j];
        }
    }
    for (int i = 1; i < n; ++i) if (rmatch[i] < 0) {
