        if (c != node) return;
        if (prev < 0) child[p] = sibling[node];
        else sibling[prev] = sibling[node];
        sibling[node] = -1;
    };
    auto attach = [&](int node, int par) {
        parent[node] = par;
        sibling[node] = child[par];
        child[par] = node;
    };

    std::vector<char> mark(N);
    int pivots = 0;
    const int MAXP = n * n + 10;

    while (pivots < MAXP) {
        double best = -EPS;
        int ei = -1, ej = -1;
