            if (x < n) flow[x] -= delta;
            else flow[x] += delta;
        }
        for (int x = V; x != apex; x = parent[x]) {
            if (x >= n) flow[x] -= delta;
            else flow[x] += delta;
        }

        // Collect path from the inside endpoint up to leave BEFORE mutating.
        bool u_inside = false;
        for (int x = U; ; x = parent[x]) {
            if (x == leave) { u_inside = true; break; }
            if (x == apex || x < 0) break;
        }
        int inside = u_inside ? U : V;
        int outside = u_inside ? V : U;

        // path[0] = inside ... path[L-1] = leave
        std::vector<int> path;
        for (int x = inside; ; x = parent[x]) {
            path.push_back(x);
            if (x == leave) break;
        }
        // save flows on those edges (flow stored on the child, i.e. path[t] for edge to its parent)
        std::vector<double> path_flow(path.size());
        for (size_t t = 0; t < path.size(); ++t) path_flow[t] = flow[path[t]];

