        detach_from_parent(leave);

        // For each consecutive pair, detach path[t] from path[t+1] (already parent) and we will
        // reattach path[t+1] as child of path[t].
        for (size_t t = 0; t + 1 < path.size(); ++t) {
            detach_from_parent(path[t]); // parent is path[t+1]
        }
        // Now re-link: path[t+1] becomes child of path[t]
        // flow on that same edge was path_flow[t] (row->col), now stored on the new child path[t+1]
        for (size_t t = 0; t + 1 < path.size(); ++t) {
            attach(path[t + 1], path[t]);
            flow[path[t + 1]] = path_flow[t];
