        double pi_out = pi[outside];
        double pi_in_needed;
        if (inside == U) {
            // inside is row, outside is col. c - pi[inside] + pi[outside] = 0 => pi[inside] = c + pi[outside]
            pi_in_needed = c_enter + pi_out;
        } else {
            // inside is col, outside is row. c - pi[outside] + pi[inside] = 0 => pi[inside] = -c + pi[outside]
            pi_in_needed = -c_enter + pi_out;
        }
        double shift = pi_in_needed - pi[inside];
        // shift whole subtree
        std::vector<int> stack = {inside};
        while (!stack.empty()) {
            int u = stack.back(); stack.pop_back();
            pi[u] += shift;
            for (int c = child[u]; c >= 0; c = sibling[c]) stack.push_back(c);
        }
