// Gauss-Seidel auction, maximization of -cost.
// eps-scaling from eps0 down to eps_final, prices carried across scales.
// Persons are scanned in a flat array; only unassigned persons bid.
extern "C" int auction(int n, const double* __restrict cost, int* __restrict rowsol) {
    std::vector<double> price(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1);
    std::vector<int> unassigned(n);

    const double eps_final = 1e-9;
    double eps = 1.0 / n;          // start relatively fine; costs are O(1), 1/n is a good start for assignment
    // Actually Bertsekas recommends start at max cost / n or larger. Try C/2.
    double C = 0;
    for (int i = 0; i < n; i += 17) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; j += 17) C = std::max(C, row[j]);
    }
    eps = std::max(C / 4.0, 1e-3);

    int scales = 0;
    while (true) {
        ++scales;
        for (int i = 0; i < n; ++i) {
            col_of_row[i] = -1;
            row_of_col[i] = -1;
            unassigned[i] = i;
        }
        int nfree = n;
        int guard = 0;
        const int guardmax = n * 4 + 100;
        while (nfree > 0 && guard < guardmax) {
            ++guard;
            int new_nfree = 0;
            for (int t = 0; t < nfree; ++t) {
                int i = unassigned[t];
                const double* row = cost + (size_t)i * n;
                double best = -1e300, second = -1e300;
                int jbest = 0;
                // manual pointer scan
                const double* pr = price.data();
                for (int j = 0; j < n; ++j) {
                    double val = -row[j] - pr[j];
                    if (val > best) {
                        second = best;
                        best = val;
                        jbest = j;
                    } else if (val > second) {
                        second = val;
                    }
                }
                double bid = pr[jbest] + (best - second) + eps;
                int prev = row_of_col[jbest];
                if (prev >= 0) {
                    col_of_row[prev] = -1;
                    unassigned[new_nfree++] = prev;
                }
                row_of_col[jbest] = i;
                col_of_row[i] = jbest;
                pr[jbest] = bid;
            }
            nfree = new_nfree;
        }
        if (nfree > 0) {
            // failed this scale; reduce eps, reset prices
            eps *= 0.5;
            std::fill(price.begin(), price.end(), 0.0);
            if (eps < eps_final) {
                for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
                return -scales;
            }
            continue;
        }
        if (eps <= eps_final) break;
        double next = eps * 0.2;
        if (next < eps_final) next = eps_final;
        eps = next;
        // keep prices
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return scales;
}
